def min_eating_speed(piles: list[int], h: int) -> int:
    low, high = 1, max(piles)
    while low < high:
        speed = (low + high) // 2
        hours = 0
        for pile in piles:
            hours += (pile + speed - 1) // speed
        if hours <= h:
            high = speed
        else:
            low = speed + 1
    return low

