def divide_integers(dividend: int, divisor: int) -> int:
    negative = (dividend < 0) != (divisor < 0)
    a = abs(dividend)
    b = abs(divisor)
    quotient = 0
    while a >= b:
        shift = 0
        while a >= (b << (shift + 1)):
            shift += 1
        a -= b << shift
        quotient += 1 << shift
    if negative:
        quotient = -quotient
    return min(max(quotient, -2**31), 2**31 - 1)

